using System; using System.Collections.Generic; namespace CollegePortal.FisGatewayAgent { public class RateLimiter { private readonly int _limit; private readonly Dictionary<string,List<DateTime>> _hits=new Dictionary<string,List<DateTime>>(); private readonly object _lock=new object(); public RateLimiter(int limit){ _limit=Math.Max(1,limit); } public bool Allow(string ip){ lock(_lock){ var now=DateTime.UtcNow; List<DateTime> list; if(!_hits.TryGetValue(ip,out list)) list=_hits[ip]=new List<DateTime>(); list.RemoveAll(x=>(now-x).TotalSeconds>60); if(list.Count>=_limit) return false; list.Add(now); return true; }}}}
